INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'abstract', 'adj./n.', '/ˈæbstrækt/', '抽象的;理论上的;(文献的)摘要', 'After his illness, Hawking''s world became one of abstract thought.', '生病之后,霍金的世界变成了一个充满抽象思维的世界。', 'Science and Scientists', 1, 0, 'senior', 'wordlist', 'elective2', 'U1', 'abstract thought', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'assistant', 'n.', '/əˈsɪstənt/', '助理;助手', 'Qian worked as a graduate assistant and helped with rocket research.', '钱学森做过研究生助理,协助进行火箭研究。', 'Science and Scientists', 2, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a graduate assistant', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'brilliant', 'adj.', '/ˈbrɪliənt/', '聪颖的;绝妙的;明亮的', 'Hawking was a brilliant scientist who changed how we see the universe.', '霍金是一位聪颖的科学家,改变了我们看待宇宙的方式。', 'Science and Scientists', 3, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a brilliant scientist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cast', 'v.', '/kɑːst/', '投射;投以(目光);投掷', 'When you stand in the light, your body casts a shadow on the wall.', '当你站在光下时,你的身体会在墙上投下影子。', 'Science and Scientists', 4, 0, 'senior', 'wordlist', 'elective2', 'U1', 'cast a shadow', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cell', 'n.', '/sel/', '细胞;小房间', 'Scientists use a microscope to study the cells of living things.', '科学家用显微镜研究生物的细胞。', 'Science and Scientists', 5, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a body cell', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cholera', 'n.', '/ˈkɒlərə/', '霍乱', 'John Snow discovered how cholera spreads through dirty water.', '约翰·斯诺发现了霍乱是如何通过脏水传播的。', 'Science and Scientists', 6, 0, 'senior', 'wordlist', 'elective2', 'U1', 'spread of cholera', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'concept', 'n.', '/ˈkɒnsept/', '概念;观念', 'The steady state theory is a difficult scientific concept to explain.', '稳态理论是一个很难解释的科学概念。', 'Science and Scientists', 7, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a key concept', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'concrete', 'adj./n.', '/ˈkɒŋkriːt/', '具体的;确实的;混凝土', 'A good scientist looks for concrete evidence before drawing conclusions.', '优秀的科学家在得出结论前会寻找确实的证据。', 'Science and Scientists', 8, 0, 'senior', 'wordlist', 'elective2', 'U1', 'concrete evidence', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'contradictory', 'adj.', '/ˌkɒntrəˈdɪktəri/', '相互矛盾的;对立的;不一致的', 'When the data seemed contradictory, the scientists ran the test again.', '当数据看起来相互矛盾时,科学家们又做了一次实验。', 'Science and Scientists', 9, 0, 'senior', 'wordlist', 'elective2', 'U1', 'contradictory results', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'decrease', 'v.', '/dɪˈkriːs/', '减少;降低', 'After Snow''s work, the number of cholera cases began to decrease.', '在斯诺的努力之后,霍乱病例的数量开始减少。', 'Science and Scientists', 10, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a substantial decrease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'defend', 'v.', '/dɪˈfend/', '保卫;防守;辩护', 'Qian believed China needed a strong air force to defend the country.', '钱学森认为中国需要一支强大的空军来保卫国家。', 'Science and Scientists', 11, 0, 'senior', 'wordlist', 'elective2', 'U1', 'defend the country', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dehydration', 'n.', '/ˌdiːhaɪˈdreɪʃn/', '脱水', 'Cholera can cause serious dehydration if it is not treated quickly.', '霍乱如果不及时治疗,会引起严重的脱水。', 'Science and Scientists', 12, 0, 'senior', 'wordlist', 'elective2', 'U1', 'cause dehydration', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'fault', 'n.', '/fɔːlt/', '弱点;过错', 'Above all, Hawking was willing to admit his own faults.', '最重要的是,霍金愿意承认自己的过错。', 'Science and Scientists', 13, 0, 'senior', 'wordlist', 'elective2', 'U1', 'admit one''s faults', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'finding', 'n.', '/ˈfaɪndɪŋ/', '发现;调查结果', 'Snow''s main finding was that cholera came from infected water.', '斯诺最主要的发现是霍乱来自被污染的水。', 'Science and Scientists', 14, 0, 'senior', 'wordlist', 'elective2', 'U1', 'announce a finding', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'framework', 'n.', '/ˈfreɪmwɜːk/', '框架;结构', 'Every good study needs a clear theoretical framework to guide it.', '每一项好的研究都需要一个清晰的理论框架来指导。', 'Science and Scientists', 15, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a theoretical framework', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'frustrated', 'adj.', '/frʌˈstreɪtɪd/', '懊恼的;沮丧的;失意的', 'The team felt frustrated when their first experiments all failed.', '当最初的实验全部失败时,团队感到很沮丧。', 'Science and Scientists', 16, 0, 'senior', 'wordlist', 'elective2', 'U1', 'feel frustrated', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'furthermore', 'adv.', '/ˌfɜːðəˈmɔː(r)/', '此外;再者', 'Hawking was brave; furthermore, he was quite determined.', '霍金很勇敢;此外,他还相当有决心。', 'Science and Scientists', 17, 0, 'senior', 'wordlist', 'elective2', 'U1', 'furthermore, ...', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'germ', 'n.', '/dʒɜːm/', '微生物;细菌;病菌', 'People once believed that cholera was caused by germs in the air.', '人们曾经认为霍乱是由空气中的病菌引起的。', 'Science and Scientists', 18, 0, 'senior', 'wordlist', 'elective2', 'U1', 'harmful germs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'gifted', 'adj.', '/ˈɡɪftɪd/', '有天赋的;天资聪慧的', 'Hawking was one of the most gifted scientists in physics.', '霍金是物理学界最有天赋的科学家之一。', 'Science and Scientists', 19, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a gifted scientist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'handle', 'n./v.', '/ˈhændl/', '把手;柄;处理;操纵', 'Snow had the handle of the water pump removed to stop the disease.', '斯诺让人卸下水泵的把手以阻止疾病传播。', 'Science and Scientists', 20, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the handle of the pump', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'household', 'n./adj.', '/ˈhaʊshəʊld/', '一家人;家庭;家喻户晓的', 'Through his discoveries, Snow became a household name in science.', '凭借自己的发现,斯诺成了科学界家喻户晓的名字。', 'Science and Scientists', 21, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a household name', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'infect', 'v.', '/ɪnˈfekt/', '使感染;传染', 'Waste had infected the water from the Broad Street pump.', '废物污染了布罗德街水泵里的水。', 'Science and Scientists', 22, 0, 'senior', 'wordlist', 'elective2', 'U1', 'infect the water', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'infection', 'n.', '/ɪnˈfekʃn/', '感染;传染', 'Clean water can stop the spread of dangerous infection.', '干净的水能阻止危险的感染传播。', 'Science and Scientists', 23, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the spread of infection', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'initial', 'adj.', '/ɪˈnɪʃl/', '最初的;开始的', 'Many problems appeared at the initial stage of the research.', '在研究的最初阶段出现了许多问题。', 'Science and Scientists', 24, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the initial stage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'intervention', 'n.', '/ˌɪntəˈvenʃn/', '介入;干预', 'Snow''s intervention helped to save thousands of lives.', '斯诺的干预帮助挽救了成千上万的生命。', 'Science and Scientists', 25, 0, 'senior', 'wordlist', 'elective2', 'U1', 'medical intervention', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'leadership', 'n.', '/ˈliːdəʃɪp/', '领导;领导才能', 'Under Qian''s leadership, China developed its own rockets.', '在钱学森的领导下,中国研制出了自己的火箭。', 'Science and Scientists', 26, 0, 'senior', 'wordlist', 'elective2', 'U1', 'under one''s leadership', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'link', 'n./v.', '/lɪŋk/', '联系;纽带;把……连接起来', 'Snow showed a clear link between dirty water and cholera.', '斯诺揭示了脏水与霍乱之间的明确联系。', 'Science and Scientists', 27, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a clear link', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'mechanical', 'adj.', '/məˈkænɪkl/', '机械的;机器的', 'Qian first studied railway mechanical engineering at university.', '钱学森在大学最初学的是铁路机械工程。', 'Science and Scientists', 28, 0, 'senior', 'wordlist', 'elective2', 'U1', 'mechanical engineering', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'microscope', 'n.', '/ˈmaɪkrəskəʊp/', '显微镜', 'Surprisingly, Snow did not use a microscope to defeat cholera.', '令人惊讶的是,斯诺并没有用显微镜来攻克霍乱。', 'Science and Scientists', 29, 0, 'senior', 'wordlist', 'elective2', 'U1', 'use a microscope', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'missile', 'n.', '/ˈmɪsaɪl/', '导弹', 'Qian was put in charge of China''s rocket and missile programme.', '钱学森负责中国的火箭和导弹计划。', 'Science and Scientists', 30, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a missile programme', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'multiple', 'adj.', '/ˈmʌltɪpl/', '多种多样的;数量多的', 'Cold-causing viruses come in multiple kinds and change quickly.', '引起感冒的病毒种类繁多,而且变化迅速。', 'Science and Scientists', 31, 0, 'senior', 'wordlist', 'elective2', 'U1', 'multiple kinds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'outstanding', 'adj.', '/aʊtˈstændɪŋ/', '优秀的;杰出的', 'His curiosity helped make him such an outstanding scientist.', '他的好奇心使他成为如此杰出的科学家。', 'Science and Scientists', 32, 0, 'senior', 'wordlist', 'elective2', 'U1', 'an outstanding scientist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'patriotic', 'adj.', '/ˌpætriˈɒtɪk/', '爱国的', 'Qian was a patriotic scientist who served his homeland.', '钱学森是一位爱国的科学家,他报效祖国。', 'Science and Scientists', 33, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a patriotic scientist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pour', 'v.', '/pɔː(r)/', '倒出;倾泻;斟', 'You can pour the strange fluid like water until you press on it.', '在你按压之前,你可以像倒水一样倒出这种奇怪的液体。', 'Science and Scientists', 34, 0, 'senior', 'wordlist', 'elective2', 'U1', 'pour it out', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'proof', 'n.', '/pruːf/', '证据;证明', 'Scientists need solid proof before they accept a new idea.', '科学家在接受新观点前需要确凿的证据。', 'Science and Scientists', 35, 0, 'senior', 'wordlist', 'elective2', 'U1', 'solid proof', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'protein', 'n.', '/ˈprəʊtiːn/', '蛋白质', 'The new medicine blocks a key protein inside the body''s cells.', '这种新药能阻断人体细胞内的一种关键蛋白质。', 'Science and Scientists', 36, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a key protein', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pure', 'adj.', '/pjʊə(r)/', '干净的;纯的;纯粹的', 'People who drank pure water were far less likely to get cholera.', '喝干净水的人得霍乱的可能性要小得多。', 'Science and Scientists', 37, 0, 'senior', 'wordlist', 'elective2', 'U1', 'pure water', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'rainbow', 'n.', '/ˈreɪnbəʊ/', '彩虹', 'In the museum, light casts your shadow in the colours of the rainbow.', '在博物馆里,光会把你的影子投成彩虹的颜色。', 'Science and Scientists', 38, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the colours of the rainbow', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'raw', 'adj.', '/rɔː/', '未处理的;生的;原始的', 'Some companies sold water that was polluted by raw waste.', '有些公司出售被未经处理的废物污染的水。', 'Science and Scientists', 39, 0, 'senior', 'wordlist', 'elective2', 'U1', 'raw waste', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'severe', 'adj.', '/sɪˈvɪə(r)/', '严重的;恶劣的;严厉的', 'Cholera was once a severe disease that killed many people.', '霍乱曾是一种夺去许多人生命的严重疾病。', 'Science and Scientists', 40, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a severe disease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'shadow', 'n.', '/ˈʃædəʊ/', '阴影;影子', 'The light at the science museum can cast many shadows of you.', '科学博物馆的灯光能投出你的许多影子。', 'Science and Scientists', 41, 0, 'senior', 'wordlist', 'elective2', 'U1', 'cast a shadow', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'shift', 'n./v.', '/ʃɪft/', '改变;转换;转移', 'Qian''s change of major was not just a shift in personal interest.', '钱学森改变专业并不只是个人兴趣的转变。', 'Science and Scientists', 42, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a shift in interest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'solid', 'adj./n.', '/ˈsɒlɪd/', '坚实的;可靠的;固体的;固体', 'It was time to calm down and do some solid work.', '是时候冷静下来,做些扎实的工作了。', 'Science and Scientists', 43, 0, 'senior', 'wordlist', 'elective2', 'U1', 'solid work', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'steady', 'adj.', '/ˈstedi/', '稳定的;平稳的', 'The steady state theory holds that the universe has no beginning.', '稳态理论认为宇宙没有起点。', 'Science and Scientists', 44, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the steady state theory', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'substantial', 'adj.', '/səbˈstænʃl/', '大量的;重大的', 'His work led to a substantial decrease in the threat of cholera.', '他的工作使霍乱的威胁大幅下降。', 'Science and Scientists', 45, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a substantial decrease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'suspect', 'v.', '/səˈspekt/', '怀疑;猜想', 'Snow began to suspect that the water was carrying the disease.', '斯诺开始怀疑是水在传播这种疾病。', 'Science and Scientists', 46, 0, 'senior', 'wordlist', 'elective2', 'U1', 'suspect that', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'telescope', 'n.', '/ˈtelɪskəʊp/', '望远镜', 'Astronomers with telescopes soon proved Hawking''s theory.', '使用望远镜的天文学家很快证明了霍金的理论。', 'Science and Scientists', 47, 0, 'senior', 'wordlist', 'elective2', 'U1', 'with telescopes', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'trace', 'v./n.', '/treɪs/', '追溯;追踪;痕迹', 'Much of the rocket technology can be traced back to Qian''s research.', '许多火箭技术都可以追溯到钱学森的研究。', 'Science and Scientists', 48, 0, 'senior', 'wordlist', 'elective2', 'U1', 'trace back to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'transform', 'v.', '/trænsˈfɔːm/', '使改观;改变形态', 'Snow transformed the way scientists study diseases.', '斯诺改变了科学家研究疾病的方式。', 'Science and Scientists', 49, 0, 'senior', 'wordlist', 'elective2', 'U1', 'transform the way', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vaccine', 'n.', '/ˈvæksiːn/', '疫苗', 'The group worked hard to develop a vaccine for malaria.', '这个团队努力研发疟疾疫苗。', 'Science and Scientists', 50, 0, 'senior', 'wordlist', 'elective2', 'U1', 'develop a vaccine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'virus', 'n.', '/ˈvaɪrəs/', '病毒', 'It is tricky to target a cold-causing virus directly.', '直接针对引起感冒的病毒是很棘手的。', 'Science and Scientists', 51, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a cold-causing virus', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vivid', 'adj.', '/ˈvɪvɪd/', '生动的;鲜明的', 'Scientists must have a vivid imagination to make new discoveries.', '科学家必须有生动的想象力才能做出新发现。', 'Science and Scientists', 52, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a vivid imagination', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u1.01', '①that 引导表语从句(从句完整、不缺成分)', 'A2', 11, '选择性必修二 U1 — 主语 + be/seem 等 + that 从句;that 只起连接作用、在从句中不充当任何成分,从句结构完整。常见主语:the truth/fact/problem/reason/idea/suggestion 等。', 1, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u1.02', '②连接代词/副词 what/where/why/how/who 引导表语从句', 'A2', 11, '选择性必修二 U1 — 从句缺成分或表疑问时用连接词:缺主语/宾语用 what/who;问地点用 where、问原因用 why、问方式/程度用 how。这些词在从句中充当成分或状语。', 2, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u1.03', '③whether / because / as if / as though 引导表语从句', 'A2', 11, '选择性必修二 U1 — 表''是否''用 whether(不用 if);''……的原因是因为……''用 because;''看上去/听起来好像''用 as if / as though(与 look/seem/sound 搭配)。', 3, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The truth was ____ the water from the pump had been infected by waste.', 'that', 'what', 'whether', 'how', 'A', '从句 ''the water had been infected'' 结构完整、不缺成分,只起连接作用 → that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The fact is ____ cholera still kills many people around the world today.', 'what', 'that', 'whether', 'why', 'B', '从句完整不缺成分 → that;what 须充当成分,whether 表是否,均不合。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'Snow''s finding was ____ dirty water carried the disease from house to house.', 'what', 'whether', 'that', 'how', 'C', '从句完整 → that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'My suggestion is ____ we collect more data before drawing any conclusion.', 'what', 'whether', 'where', 'that', 'D', 'suggestion 后表语从句用 that,从句完整且谓语用虚拟(we collect)→ that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'One problem was ____ the team could not agree on a single theory.', 'that', 'what', 'whether', 'how', 'A', '从句完整 → that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The reason for his success is ____ he never stopped asking questions.', 'why', 'that', 'whether', 'what', 'B', '主语已是 the reason,表语从句说明内容、从句完整 → that(不再用 why)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The good news is ____ the number of cholera cases has dropped sharply.', 'what', 'whether', 'that', 'how', 'C', '从句完整 → that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'His belief was ____ every child starts out as a scientist.', 'what', 'whether', 'why', 'that', 'D', '从句完整 → that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The point is ____ Snow used maps and statistics instead of a microscope.', 'that', 'what', 'whether', 'how', 'A', '从句完整 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The idea behind the experiment is ____ a fluid can act like a solid.', 'what', 'that', 'whether', 'where', 'B', '从句完整 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'What surprised us was ____ Snow did not use any common medical tools.', 'what', 'whether', 'that', 'how', 'C', '表语从句 ''Snow did not use ...'' 完整 → that;主语处的 what 已用。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The trouble was ____ no institute in China then offered rocket science.', 'what', 'whether', 'why', 'that', 'D', '从句完整 → that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'His reply was simply ____ Chinese people could make missiles too.', 'that', 'what', 'whether', 'how', 'A', '从句完整 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The conclusion was ____ the pump in Broad Street had spread the disease.', 'what', 'that', 'whether', 'where', 'B', '从句完整 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'One of his strengths was ____ he was willing to admit his own faults.', 'what', 'whether', 'that', 'how', 'C', '从句完整 → that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The result was ____ water companies began to sell clean water.', 'what', 'whether', 'why', 'that', 'D', '从句完整 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'What worried the team was ____ the early experiments all failed.', 'that', 'what', 'whether', 'how', 'A', '表语从句完整 → that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'Our hope is ____ a safe vaccine will be ready within a few years.', 'what', 'that', 'whether', 'where', 'B', '从句完整 → that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The first sign was ____ many deaths happened near the same pump.', 'what', 'whether', 'that', 'how', 'C', '从句完整 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.01'), 'The amazing thing about him was ____ art gave him ideas for his science.', 'what', 'whether', 'why', 'that', 'D', '从句完整 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'That was exactly ____ happened at the initial stage of the research.', 'what', 'that', 'whether', 'because', 'A', '从句 ''___ happened'' 缺主语 → 用 what(充当主语);that 不充当成分。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'Science is simply ____ you can do with curiosity and evidence.', 'that', 'what', 'whether', 'as if', 'B', '从句 ''you can do ___'' 缺宾语 → what。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'What John Snow showed to the world was ____ cholera could be overcome.', 'that', 'what', 'how', 'because', 'C', '表语从句 ''cholera could be overcome ___'' 表''以何种方式被攻克'' → how。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The question now is ____ we can reduce the cost without losing the effect.', 'that', 'what', 'whether', 'how', 'D', '从句不缺主宾、问''用什么方式降低成本'' → how。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The real issue was ____ they should carry out the research in the first place.', 'why', 'that', 'what', 'because', 'A', '从句不缺主宾、问''为何要做这项研究'' → why。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'A laboratory is ____ scientists test their ideas with careful experiments.', 'that', 'where', 'what', 'whether', 'B', '从句完整、说明''在何处'' → where(表地点)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'That is ____ matters most to a true scientist: curiosity and creativity.', 'that', 'whether', 'what', 'as if', 'C', '从句 ''___ matters most'' 缺主语 → what。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The key issue is ____ they communicate their results to the public.', 'that', 'what', 'because', 'how', 'D', '从句不缺主宾、问方式 → how。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The puzzle was ____ the disease kept returning to the very same street.', 'why', 'that', 'what', 'whether', 'A', '从句完整、问原因 → why。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'This museum is ____ visitors can see their own shadows in rainbow colours.', 'that', 'where', 'what', 'because', 'B', '从句完整、表地点 → where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'Curiosity is ____ turns an ordinary child into a future scientist.', 'that', 'whether', 'what', 'how', 'C', '从句 ''___ turns ...'' 缺主语 → what。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The mystery was ____ some people drank the water and yet survived.', 'that', 'what', 'whether', 'why', 'D', '从句完整、问原因 → why。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'A good question is often ____ a scientist begins a brand-new study.', 'how', 'that', 'what', 'because', 'A', '从句完整、问方式 → how。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'His strongest quality was ____ made him so creative: a love of art.', 'that', 'what', 'whether', 'where', 'B', '从句 ''___ made him so creative'' 缺主语 → what。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The lab is ____ the team spent every evening checking their results.', 'that', 'what', 'where', 'whether', 'C', '从句完整、表地点 → where。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The hard part was ____ they could persuade one another to share data.', 'that', 'what', 'because', 'how', 'D', '从句不缺主宾、问方式 → how。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'That is ____ the early scientists could not explain about the universe.', 'what', 'that', 'whether', 'why', 'A', '从句 ''could not explain ___'' 缺宾语 → what。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The reason behind the dispute was ____ each side wanted a different theory.', 'that', 'why', 'what', 'whether', 'B', '从句完整、问原因 → why。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The classroom is ____ I first learned to look at the world like a scientist.', 'that', 'what', 'where', 'because', 'C', '从句完整、表地点 → where。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.02'), 'The final challenge is ____ they analyse the data to answer the questions.', 'that', 'what', 'whether', 'how', 'D', '从句完整、问方式 → how。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The problem was ____ the team had enough time to test every theory.', 'whether', 'that', 'because', 'as if', 'A', '句意''是否有足够时间'',表''是否''用 whether(不用 if 引导表语从句)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'It looked ____ all the theories were useful, but only one really was.', 'that', 'as if', 'because', 'whether', 'B', '系动词 look + ''好像'' → as if / as though。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The only reason he switched majors was ____ China badly needed an air force.', 'that', 'whether', 'because', 'as if', 'C', '''原因是因为……'',表语从句用 because 说明原因。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The doubt in his mind was ____ the new medicine would really be safe.', 'that', 'because', 'as though', 'whether', 'D', '句意''是否安全'',表''是否'' → whether。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'It seemed ____ the disease followed the water rather than the air.', 'as if', 'that', 'because', 'whether', 'A', 'seem + ''好像'' → as if / as though。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The reason cholera spread so fast was ____ the water had been infected.', 'that', 'because', 'whether', 'as if', 'B', '''……如此快的原因是因为……'' → because。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The first question was ____ the team should target the host or the virus.', 'that', 'because', 'whether', 'as though', 'C', '句意''是否……或……'',二选一用 whether。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The sky looked ____ it would rain before the field experiment ended.', 'that', 'because', 'whether', 'as if', 'D', 'look + ''好像'' → as if。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The reason he is remembered is ____ he served his country with devotion.', 'because', 'that', 'whether', 'as if', 'A', '强调''原因是因为……'' → because。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'Our worry was ____ the experiment could be repeated by other scientists.', 'that', 'whether', 'because', 'as though', 'B', '句意''是否能被重复'',表''是否'' → whether。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'It sounded ____ the two theories simply could not both be true.', 'that', 'because', 'as if', 'whether', 'C', 'sound + ''好像'' → as if / as though。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The reason the handle was removed was ____ the pump kept spreading cholera.', 'that', 'whether', 'as if', 'because', 'D', '''……被卸下的原因是因为……'' → because。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'What we discussed was ____ the data really supported our first idea.', 'whether', 'that', 'because', 'as though', 'A', '句意''是否真的支持'',表''是否'' → whether。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'For a moment it felt ____ the whole project was about to fail completely.', 'that', 'as if', 'because', 'whether', 'B', 'feel + ''好像'' → as if / as though。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The reason maps mattered so much was ____ they revealed a clear pattern.', 'that', 'whether', 'because', 'as if', 'C', '强调''……重要的原因是因为……'' → because。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The real concern was ____ a cheaper vaccine would still work well enough.', 'that', 'because', 'as though', 'whether', 'D', '句意''是否仍然有效'',表''是否'' → whether。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'It seemed ____ Hawking could see truths that others were afraid to imagine.', 'as if', 'that', 'because', 'whether', 'A', 'seem + ''好像'' → as if / as though。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The reason he kept calm was ____ he trusted his solid, careful work.', 'that', 'because', 'whether', 'as if', 'B', '''……保持冷静的原因是因为……'' → because。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'The question we left unanswered was ____ the side effects could be avoided.', 'that', 'because', 'whether', 'as though', 'C', '句意''是否能避免'',表''是否'' → whether。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U1' AND code='e2u1.03'), 'At first it looked ____ targeting a protein would never beat the virus.', 'that', 'because', 'whether', 'as if', 'D', 'look + ''好像'' → as if / as though。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'John Snow and Cholera', 'In the past, many people in London died from cholera, but no one knew how it spread. Most doctors believed that the disease was caused by bad air or by germs floating around the city. John Snow was not so sure. During the outbreak of 1854, he marked on a map every place where people had died. He soon saw that most of the deaths were close to a single water pump in Broad Street. Snow began to suspect that the water, not the air, was carrying the disease. He learned that the pump water had been infected by waste. To test his idea, he had the handle of the pump removed so that no one could use it. After that, the number of new cases quickly fell. Snow had no microscope and used no medicine. His most powerful tools were a map, careful thinking and clear evidence. Because of this work, he is now seen as the father of modern epidemiology.', '说明·约翰·斯诺攻克霍乱', 162, '[{"q":"What did most doctors believe caused cholera?","answer":"A","options":["Bad air or germs in the city.","Dirty water from one pump.","Too much medicine.","A lack of fresh food."],"explanation":"原文 ''caused by bad air or by germs'' 的转述。"},{"q":"Why did Snow have the pump handle removed?","answer":"B","options":["To repair the broken pump.","To stop people from using the infected water.","To sell the water elsewhere.","To take it to a museum."],"explanation":"原文 ''so that no one could use it'' 的转述,目的是停用受污染的水。"},{"q":"What does the passage say about Snow''s tools?","answer":"A","options":["He depended on maps, thinking and evidence.","He relied mainly on a microscope.","He used strong new medicines.","He copied other doctors'' methods."],"explanation":"原文 ''a map, careful thinking and clear evidence'' 的转述。"}]'::jsonb, '[{"word":"cholera","cn":"霍乱"},{"word":"pump","cn":"水泵"},{"word":"infect","cn":"使感染;污染"},{"word":"handle","cn":"把手"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'How Scientists Work', 'What exactly do scientists do all day? Many people imagine them only mixing colourful liquids in a lab, but the real work begins with a question. A scientist notices something strange in the world and asks why it happens. Next comes a guess, or hypothesis, about the possible answer. The scientist then looks for evidence to test that guess. This may mean taking careful measurements, collecting data, or running the same experiment again and again. The numbers are studied, and conclusions are slowly drawn from what the data show. One result, however, is never enough. Other scientists must be able to repeat the study and reach the same conclusion before the finding is trusted. Finally, the results are shared so that everyone can benefit. This step matters just as much as the others, because science grows only when ideas are passed on. In this way, asking questions and testing answers turn ordinary curiosity into real knowledge about the world.', '说明·科学方法与探究步骤', 159, '[{"q":"According to the passage, where does real scientific work begin?","answer":"B","options":["With mixing colourful liquids.","With a question about the world.","With sharing the results.","With reading other studies."],"explanation":"原文 ''the real work begins with a question'' 的转述。"},{"q":"Why is one result not enough in science?","answer":"C","options":["Because experiments are too expensive.","Because scientists dislike numbers.","Because the finding must be repeated by others before it is trusted.","Because data cannot be measured."],"explanation":"原文 ''Other scientists must be able to repeat the study … before the finding is trusted'' 的转述。"},{"q":"Why does the writer say sharing results matters?","answer":"D","options":["It saves time in the lab.","It makes experiments shorter.","It replaces the need for evidence.","Because progress depends on passing ideas to other people."],"explanation":"原文 ''science grows only when ideas are passed on'' 的转述。"}]'::jsonb, '[{"word":"finding","cn":"发现;调查结果"},{"word":"proof","cn":"证据;证明"},{"word":"concrete","cn":"具体的;确实的"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'The Father of China''s Aerospace', 'Few scientists have shaped China''s space science as much as Qian Xuesen. Born in Shanghai in 1911, he first studied railway mechanical engineering. After war broke out in 1932, he chose to switch his major to aviation, for he believed that a strong air force was needed to protect the country. In 1935 he travelled to the United States for further study and became a pioneer in jet and rocket technology. Yet his heart remained with his homeland. After overcoming many difficulties, he returned to China in 1955 and was put in charge of its rocket and missile programme. At that time the country was poor and had no experts in this field, but Qian refused to be discouraged. When asked whether Chinese people could really build missiles, he replied firmly, ''Why not?'' Under his leadership China developed its own rockets and, in 1970, launched its first satellite. People honoured him because he served his country with great effort and devotion.', '人物·钱学森', 161, '[{"q":"Why did Qian switch his major to aviation?","answer":"A","options":["He felt China must build a powerful air force for its defence.","He disliked railway engineering.","His teachers told him to.","He wanted to travel abroad."],"explanation":"原文 ''a strong air force was needed to protect the country'' 的转述。"},{"q":"What was China''s situation when Qian took charge of the programme?","answer":"B","options":["It already had many rocket experts.","It was poor and lacked experts in the field.","It had finished building its rockets.","It was the world leader in space."],"explanation":"原文 ''the country was poor and had no experts in this field'' 的转述。"},{"q":"Why did people honour Qian?","answer":"C","options":["Because he became rich abroad.","Because he avoided all hardship.","Because he devoted his whole effort to serving the nation.","Because he never left the United States."],"explanation":"原文 ''served his country with great effort and devotion'' 的转述。"}]'::jsonb, '[{"word":"mechanical","cn":"机械的"},{"word":"missile","cn":"导弹"},{"word":"patriotic","cn":"爱国的"},{"word":"leadership","cn":"领导才能"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A World of Pure Thought', 'Stephen Hawking was one of the most gifted scientists in physics. Most people picture him in a wheelchair, unable to move and using a computer to speak. Yet he first became famous while he was still healthy enough to walk. As a young student in 1964, he listened to a lecture by a well-known professor who supported the steady state theory of the universe. During the questions afterwards, Hawking stood up and pointed out a mistake in the professor''s maths. When the maths was corrected, it showed that the big bang theory, not the steady state theory, was right. Soon astronomers with telescopes proved Hawking''s own work as well. So what made him a genius? Besides being brilliant, he was brave enough to say and dream what others feared to. Furthermore, he was very determined, which helped him in science and even more in his long fight against his disease. Above all, he was always willing to admit his faults.', '人物·史蒂芬·霍金', 160, '[{"q":"When did Hawking first become famous?","answer":"D","options":["After he lost the use of his muscles.","Only near the end of his life.","Before he entered university.","While he was still able to walk."],"explanation":"原文 ''while he was still healthy enough to walk'' 的转述。"},{"q":"What did the corrected maths finally show?","answer":"A","options":["That the universe really began with a big bang.","That the professor had been right.","That neither theory worked.","That telescopes were useless."],"explanation":"原文 ''the big bang theory, not the steady state theory, was right'' 的转述。"},{"q":"Which quality does the writer praise most at the end?","answer":"B","options":["His wealth.","His willingness to admit his faults.","His good luck.","His fear of new ideas."],"explanation":"原文末句 ''Above all, he was always willing to admit his faults'' 的转述。"}]'::jsonb, '[{"word":"gifted","cn":"有天赋的"},{"word":"steady","cn":"稳定的"},{"word":"telescope","cn":"望远镜"},{"word":"fault","cn":"过错;缺点"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'What Is the Scientific Spirit?', 'Being clever is not enough to make a great scientist. Cleverness can solve problems that are already known, but the scientific spirit pushes a person to ask what no one has asked before. People with this spirit are curious; they keep wondering why the world works as it does. They are also honest, ready to follow the evidence even when it goes against their own ideas. When the data are contradictory, they do not hide the problem but look for a better answer. Such people are brave, willing to share a strange idea that others may laugh at. They are patient, too, repeating an experiment many times until the result is solid. Most of all, they are humble enough to admit a mistake and start again. These qualities matter far more than any single discovery, for they are what keep science moving forward. A great scientist, in the end, is someone who never stops asking, testing and learning.', '说明·科学探究精神', 158, '[{"q":"What does the writer say cleverness alone cannot do?","answer":"C","options":["Solve any known problem.","Help with simple maths.","Push a person to ask brand-new questions.","Make a person curious about food."],"explanation":"原文对比 ''Cleverness can solve … but the scientific spirit pushes a person to ask what no one has asked before'' 的转述。"},{"q":"How do scientists with this spirit treat contradictory data?","answer":"D","options":["They throw the data away.","They stop the research at once.","They blame other people.","They search for a better answer instead of hiding the problem."],"explanation":"原文 ''they do not hide the problem but look for a better answer'' 的转述。"},{"q":"According to the passage, why do these qualities matter so much?","answer":"A","options":["They are the very things that drive science onward.","They make scientists rich.","They make experiments shorter.","They replace the need for evidence."],"explanation":"原文 ''they are what keep science moving forward'' 的转述。"}]'::jsonb, '[{"word":"contradictory","cn":"相互矛盾的"},{"word":"solid","cn":"可靠的;扎实的"},{"word":"vivid","cn":"生动的"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Curiosity and Creativity', 'Why do some people become great scientists while others, just as clever, do not? Part of the answer seems to lie in two simple qualities: curiosity and creativity. Curious people are never quite satisfied with the usual explanation. They keep asking why, and that question often leads them to a door no one has opened before. Creativity then lets them imagine answers that sound strange at first. A famous scientist once said that every child starts out as a scientist, full of a sense of wonder. Sadly, many of us lose that wonder as we grow up and learn to accept things as they are. Great scientists, however, hold on to it. They are willing to look foolish and to try ideas that others think are crazy. Interestingly, their love of music, art or drawing often feeds this imagination. By keeping a child''s curiosity and an artist''s creativity, they manage to see the world in fresh and surprising ways.', '说明·科学家的好奇心与创造力', 159, '[{"q":"What two qualities does the writer focus on?","answer":"B","options":["Wealth and luck.","Curiosity and creativity.","Speed and strength.","Memory and patience."],"explanation":"原文 ''two simple qualities: curiosity and creativity'' 的转述。"},{"q":"What did the famous scientist say about children?","answer":"C","options":["They never ask questions.","Only a few children are clever.","Each young child begins life as a wonder-filled scientist.","Children should not study science."],"explanation":"原文 ''every child starts out as a scientist, full of a sense of wonder'' 的转述。"},{"q":"How does a love of art help these scientists?","answer":"D","options":["It makes them give up science.","It earns them more money.","It replaces their need to ask questions.","It feeds their imagination."],"explanation":"原文 ''their love of music, art or drawing often feeds this imagination'' 的转述。"}]'::jsonb, '[{"word":"abstract","cn":"抽象的"},{"word":"concept","cn":"概念"},{"word":"transform","cn":"改变"}]'::jsonb, 2, 'elective2', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'A Strange Fluid', 'In class today, our teacher showed us a very (1)____ experiment. She mixed equal parts of water and cornflour in a bowl. The mixture looked like a normal (2)____ that you could pour from one hand to another. But then she pressed it hard with her finger, and it suddenly became as (3)____ as concrete. As soon as she stopped pressing, it turned soft again. We could not (4)____ our eyes. The teacher explained that this odd fluid can (5)____ from a liquid into a solid when pressure is put on it. She asked us to (6)____ why this happens, just as a real scientist would. None of us knew the (7)____ at first, so we began to make guesses. This little (8)____ showed us that something can act as two things at the same time. More importantly, it taught us to ask (9)____ about the world around us. That, our teacher said, is the (10)____ of every great discovery.', 160, 2, '[{"q":"1","answer":"A","options":["strange","boring","dirty","quiet"],"explanation":"a strange experiment 奇怪的实验。"},{"q":"2","answer":"B","options":["stone","liquid","book","song"],"explanation":"a normal liquid 普通液体,可倒。"},{"q":"3","answer":"C","options":["soft","warm","hard","wet"],"explanation":"as hard as concrete 像混凝土一样硬。"},{"q":"4","answer":"D","options":["close","open","wash","believe"],"explanation":"could not believe our eyes 不敢相信眼睛。"},{"q":"5","answer":"A","options":["change","hide","fall","wait"],"explanation":"change from a liquid into a solid 由液变固。"},{"q":"6","answer":"B","options":["forget","ask","sell","lose"],"explanation":"ask why 追问为什么。"},{"q":"7","answer":"C","options":["price","noise","answer","weather"],"explanation":"know the answer 知道答案。"},{"q":"8","answer":"D","options":["holiday","market","garden","experiment"],"explanation":"this little experiment 这个小实验。"},{"q":"9","answer":"A","options":["questions","prices","songs","tickets"],"explanation":"ask questions 提问。"},{"q":"10","answer":"B","options":["price","start","noise","shadow"],"explanation":"the start of every discovery 每个发现的起点。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'A Day in the Lab', 'My sister works as a young researcher, and last week she let me (1)____ a whole day in her lab. I had imagined scientists doing exciting things, but most of the day was quiet and (2)____. First she wrote down a clear (3)____ that she wanted to answer. Then she carefully took many (4)____ and wrote every number in a notebook. When two of her results seemed (5)____, she did not get angry; she simply ran the test (6)____. ''A good scientist must be (7)____,'' she told me with a smile. By the afternoon she had enough (8)____ to draw a careful conclusion. She reminded me that one result alone is never (9)____, because others must be able to repeat it. Watching her work all day, I finally understood that real science is built on patience and (10)____ thinking rather than on lucky guesses.', 144, 2, '[{"q":"1","answer":"C","options":["sell","throw","spend","lose"],"explanation":"spend a whole day 度过一整天。"},{"q":"2","answer":"D","options":["loud","funny","rich","careful"],"explanation":"quiet and careful 安静而细致。"},{"q":"3","answer":"A","options":["question","price","noise","garden"],"explanation":"a clear question 一个清晰的问题。"},{"q":"4","answer":"B","options":["songs","measurements","prices","tickets"],"explanation":"take measurements 进行测量。"},{"q":"5","answer":"C","options":["happy","late","contradictory","empty"],"explanation":"seemed contradictory 看起来相互矛盾。"},{"q":"6","answer":"D","options":["never","alone","abroad","again"],"explanation":"run the test again 重新做实验。"},{"q":"7","answer":"A","options":["patient","angry","lazy","afraid"],"explanation":"must be patient 必须有耐心。"},{"q":"8","answer":"B","options":["noise","data","weather","price"],"explanation":"enough data 足够的数据。"},{"q":"9","answer":"C","options":["wrong","empty","enough","free"],"explanation":"never enough 永远不够。"},{"q":"10","answer":"D","options":["lucky","loud","rich","careful"],"explanation":"careful thinking 缜密的思考。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'Clean Water Saves Lives', 'Long ago, many cities had no safe water, and dangerous diseases spread (1)____. People did not understand that the (2)____ they drank could make them ill. Some companies sold water taken straight from the river, even though it was (3)____ by waste. Those who drank it were far more (4)____ to fall ill than those who boiled their water first. Over time, scientists showed a clear (5)____ between dirty water and disease. Thanks to their (6)____, water companies slowly began to sell (7)____ water that was safe to drink. As a result, the (8)____ of many illnesses fell sharply year after year. Even today, however, the work is not (9)____, for some places still lack clean water. By keeping our water (10)____, we protect the health of whole towns and cities.', 131, 2, '[{"q":"1","answer":"A","options":["quickly","slowly","quietly","kindly"],"explanation":"spread quickly 迅速传播。"},{"q":"2","answer":"B","options":["song","water","noise","price"],"explanation":"the water they drank 他们喝的水。"},{"q":"3","answer":"C","options":["sold","lost","infected","hidden"],"explanation":"infected by waste 被废物污染。"},{"q":"4","answer":"D","options":["famous","afraid","polite","likely"],"explanation":"more likely to fall ill 更可能生病。"},{"q":"5","answer":"A","options":["link","price","song","noise"],"explanation":"a clear link 明确的联系。"},{"q":"6","answer":"B","options":["holiday","work","market","garden"],"explanation":"thanks to their work 多亏他们的努力。"},{"q":"7","answer":"C","options":["noisy","dirty","pure","empty"],"explanation":"pure water 干净的水。"},{"q":"8","answer":"D","options":["price","weather","garden","number"],"explanation":"the number of illnesses 疾病的数量。"},{"q":"9","answer":"A","options":["finished","begun","lost","sold"],"explanation":"the work is not finished 工作尚未完成。"},{"q":"10","answer":"B","options":["dirty","clean","loud","warm"],"explanation":"keep our water clean 保持水的洁净。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'A Visit to the Science Museum', 'Last weekend my class visited a science museum, and it was the best (1)____ of the term. The first thing we saw was a giant dish that (2)____ your voice back so you could talk to a friend far (3)____. Next, we stepped in front of a bright light that cast our (4)____ on the wall in the colours of the rainbow. My favourite room was full of (5)____ that you could play with your feet, but instead of music they made the (6)____ of animals. One machine even let us look through a (7)____ at tiny living cells. Everywhere we went, a guide encouraged us to (8)____ questions about what we saw. By the end of the day, I had learned that science can be both useful and (9)____. I left the museum feeling more (10)____ about the world than ever before.', 143, 2, '[{"q":"1","answer":"C","options":["price","noise","trip","song"],"explanation":"the best trip 最棒的一次出游。"},{"q":"2","answer":"D","options":["sold","lost","hid","sent"],"explanation":"sent your voice back 把声音送回。"},{"q":"3","answer":"A","options":["away","below","above","inside"],"explanation":"far away 在远处。"},{"q":"4","answer":"B","options":["prices","shadows","songs","tickets"],"explanation":"cast our shadows 投下影子。"},{"q":"5","answer":"C","options":["books","coins","keys","plates"],"explanation":"keys you could play with your feet 用脚踩的琴键。"},{"q":"6","answer":"D","options":["price","weather","garden","sounds"],"explanation":"the sounds of animals 动物的声音。"},{"q":"7","answer":"A","options":["microscope","window","door","wall"],"explanation":"look through a microscope 透过显微镜看。"},{"q":"8","answer":"B","options":["sell","ask","hide","lose"],"explanation":"ask questions 提问。"},{"q":"9","answer":"C","options":["boring","sad","fun","empty"],"explanation":"useful and fun 既有用又有趣。"},{"q":"10","answer":"D","options":["afraid","angry","tired","curious"],"explanation":"more curious 更加好奇。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'Working on a Vaccine', 'A team of scientists once spent years trying to (1)____ a new vaccine for malaria. At the (2)____ stage, nothing seemed to work, and the members often felt (3)____. Their early experiments gave (4)____ results that did not agree with one another. Some believed they should target the disease in one way, while others were (5)____ that a different method was better. The real problem was (6)____ they could agree on a single theory to follow. After many failures, they decided to calm down and do some (7)____ work step by step. Slowly, the data began to (8)____ in the same direction. The team learned that science needs not only clever ideas but also (9)____ and teamwork. In the end, their careful effort brought them much closer to a (10)____ that could protect millions of people.', 136, 2, '[{"q":"1","answer":"A","options":["develop","sell","lose","hide"],"explanation":"develop a vaccine 研发疫苗。"},{"q":"2","answer":"B","options":["last","initial","empty","free"],"explanation":"the initial stage 最初阶段。"},{"q":"3","answer":"C","options":["happy","rich","frustrated","polite"],"explanation":"felt frustrated 感到沮丧。"},{"q":"4","answer":"D","options":["songs","prices","tickets","contradictory"],"explanation":"contradictory results 相互矛盾的结果。"},{"q":"5","answer":"A","options":["sure","late","empty","free"],"explanation":"were sure 确信。"},{"q":"6","answer":"B","options":["because","whether","price","noise"],"explanation":"the problem was whether 问题在于是否。"},{"q":"7","answer":"C","options":["lazy","loud","solid","rich"],"explanation":"solid work 扎实的工作。"},{"q":"8","answer":"D","options":["sell","hide","lose","point"],"explanation":"point in the same direction 指向同一方向。"},{"q":"9","answer":"A","options":["patience","money","noise","luck"],"explanation":"patience and teamwork 耐心与团队合作。"},{"q":"10","answer":"B","options":["price","vaccine","garden","noise"],"explanation":"a vaccine 一种疫苗。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U1', 'The Power of Asking Questions', 'One of the best ways to understand a science text is to keep (1)____ questions while you read. Good readers do not just take in the words; they wonder (2)____ the writer makes each point. When my teacher gave us a difficult (3)____ about scientists, she told us to stop after every paragraph and ask ourselves a (4)____. This simple habit helped the ideas become much (5)____ in our minds. We asked what the writer meant, (6)____ the experiment worked, and why the result mattered. Slowly, the hard text began to make (7)____. The same skill, our teacher said, is what real scientists (8)____ every day, since their work always starts with a question. By the end of the lesson, we all agreed that asking questions had made the reading far less (9)____. It also made us feel more (10)____ in our own ability to learn.', 146, 2, '[{"q":"1","answer":"C","options":["selling","hiding","asking","losing"],"explanation":"keep asking questions 不断提问。"},{"q":"2","answer":"D","options":["price","noise","song","why"],"explanation":"wonder why 想知道为什么。"},{"q":"3","answer":"A","options":["text","garden","market","ticket"],"explanation":"a difficult text 一篇难读的文章。"},{"q":"4","answer":"B","options":["song","question","price","noise"],"explanation":"ask ourselves a question 问自己一个问题。"},{"q":"5","answer":"C","options":["louder","richer","clearer","wetter"],"explanation":"much clearer 清晰得多。"},{"q":"6","answer":"D","options":["price","noise","song","how"],"explanation":"how the experiment worked 实验如何运作。"},{"q":"7","answer":"A","options":["sense","money","noise","weather"],"explanation":"make sense 变得讲得通。"},{"q":"8","answer":"B","options":["sell","do","hide","lose"],"explanation":"what scientists do 科学家所做的事。"},{"q":"9","answer":"C","options":["happy","rich","scary","free"],"explanation":"far less scary 没那么可怕。"},{"q":"10","answer":"D","options":["afraid","angry","tired","confident"],"explanation":"more confident 更自信。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·对话 Joining the Science Club', '选择性必修二 U1 · dialogue', 3, 'Lucy: Hi Tom, are you going to join the science club this year?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·短文 What Scientists Really Do', '选择性必修二 U1 · passage', 2, 'Many people think scientists only mix liquids in a lab.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·对话 In the Laboratory', '选择性必修二 U1 · dialogue', 3, 'David: Maria, our first two results don''t match at all. I feel frustrated.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·短文 The Story of Stephen Hawking', '选择性必修二 U1 · passage', 2, 'Stephen Hawking was a gifted scientist who studied the universe.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·对话 Advice on Doing Research', '选择性必修二 U1 · dialogue', 3, 'Anna: I want to start a small research project, but I don''t know how to begin.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U1 听力·短文 A Tip for Young Scientists', '选择性必修二 U1 · passage', 2, 'Here is a simple tip for any young person who loves science.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Write about a Scientist and the Scientific Spirit(写一位科学家与科学精神)', 'Write about a Scientist and the Scientific Spirit(写一位科学家与科学精神)', '请用英语写一篇约100词的短文,介绍一位你敬佩的科学家(如约翰·斯诺、钱学森或史蒂芬·霍金),内容包括:① 他/她是谁、做出了什么贡献;② 用一两个事例说明使他/她成功的科学精神品质(如好奇、诚实、勇敢、坚持);③ 这位科学家给你的启发。注意用恰当的连接词,行文连贯。', 'Write an essay (about 100 words) about a scientist you admire (e.g. John Snow, Qian Xuesen or Stephen Hawking). Include: 1) who the person was and what he/she achieved; 2) one or two examples of the qualities of the scientific spirit (such as curiosity, honesty, courage or determination) that made him/her succeed; 3) what the scientist inspires in you. Use suitable linking words to make your writing flow.', '["介绍人物与贡献(... was a great scientist who ... / made an important discovery ...)","用事例说明科学精神品质(For example, ... / This shows that he was ...)","谈对你的启发(His story tells me that ... / I have learned that ...)","用连接词连贯(Besides, Furthermore, Above all)"]'::jsonb, 70, 100, 'John Snow was a great scientist who first showed how cholera spreads. During a deadly outbreak, he marked every death on a map and discovered that the disease came from one infected water pump. Instead of trusting old ideas, he followed the evidence, which shows his honesty and curiosity. Furthermore, he was brave enough to remove the pump handle, and soon the new cases fell. Above all, he never stopped asking questions. His story tells me that the scientific spirit is not only about being clever, but about staying curious, honest and determined. I hope to face my own problems in the same careful way.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["John Snow was a great scientist who first showed how cholera spreads.","Instead of trusting old ideas, he followed the evidence, which shows his honesty.","He was brave enough to remove the pump handle, and soon the new cases fell.","The scientific spirit is not only about being clever, but about staying curious and determined."]'::jsonb, '[{"wrong":"The truth is he was right.","correct":"The truth is that he was right.","note":"表语从句用 that 引导,书面语中不宜省略。"},{"wrong":"The question is that we can solve it.","correct":"The question is how we can solve it.","note":"从句不缺主宾、表''以何种方式'',用 how 而非 that。"},{"wrong":"The problem is if we have enough time.","correct":"The problem is whether we have enough time.","note":"表语从句表''是否''用 whether,不用 if。"}]'::jsonb, '【科学家与科学精神 结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective2', 'U1', '{"title":"表语从句(Predicative Clauses)速查","intro":"结构:主语 + 系动词(be / seem / look / sound / remain) + 表语从句。判断口诀:从句完整不缺成分→that;缺主语/宾语→what/who;表疑问(何处/何因/如何)→where/why/how;表''是否''→whether;说原因→because;''好像''→as if / as though。","table":{"headers":["引导词","用法 / 例句"],"rows":[["that","从句完整、不充当成分:The truth is that he was right."],["what / who","从句缺主语或宾语:That is what matters. / 充当主宾"],["where / why / how","从句问地点/原因/方式:The question is how we can solve it."],["whether","表''是否''(不用 if):The problem is whether we have time."],["because / as if","说原因 because;''好像'' as if:It looks as if it will rain."]]},"specialRules":[{"rule":"that 在从句中不充当任何成分,从句结构完整","mark":"The fact is that cholera still exists.(完整→that)"},{"rule":"what 充当主语或宾语;缺成分才用 what,不可用 that","mark":"Science is what you can do.(do 缺宾语→what)"},{"rule":"表''是否''用 whether,if 不引导表语从句","mark":"The question is whether √ / if ×"},{"rule":"look / seem / sound + as if / as though 表''好像''","mark":"It seemed as if all the theories were useful."}],"why":["表语从句放在系动词后,补充说明主语的内容。先看从句是否缺主语/宾语:缺→用 what/who;不缺再看句意:陈述事实→that,问地点/原因/方式→where/why/how,问是否→whether,说原因→because,表''好像''→as if。"],"gaokaoPoints":["that 与 what 的区分(看从句是否缺成分);whether 与 if(表语从句只用 whether)是语法填空与改错高频点。","the reason is that ...(不再用 why);the question/problem is how/whether ... 为固定高频搭配。"],"examVsReal":[{"exam":"The truth is that he was right.(考试/书面)","real":"The truth is, he was right.","note":"考试书面语保留 that;口语中常省略 that 或用逗号停顿"},{"exam":"It looks as if it will rain.(考试)","real":"It looks like it''s gonna rain.","note":"考试用 as if + 从句;口语里常用 like 代替 as if"}]}'::jsonb);
